/**
 * Closed lifecycle states for a `EvidenceBundle`'s verification status.
 *
 * `PENDING` is the initial state when a bundle is first written. `VERIFIED`
 * means all `VerificationCheck` items passed. `INCOMPLETE` means reachability
 * or digest checks found missing records but the operator accepted the partial
 * bundle. `FAILED` means at least one blocking integrity check failed.
 */
export type BundleVerificationState =
  "pending" | "verified" | "incomplete" | "failed";

/**
 * Closed set of serialisations of one modelo calculation report.
 *
 * Attributes: CSV: The report's rows as a delimited table with fixed columns,
 * above a commented preamble carrying the report's header facts. Machine
 * readable, and the format a reviewer diffs or loads into a sheet. PDF: The
 * calculation summary: a tagged, archival page rendering of the report for a
 * person to read, carrying the report's canonical bytes, its CSV and a signed
 * integrity statement as embedded files. Needs the optional `pdf` extra to
 * write, and nothing optional to verify.
 */
export type CalculationReportDocumentFormat = "csv" | "pdf";

/**
 * What one reported row does in the declaration.
 *
 * Derived from the registry's declared `input_kind` and `semantic_role` and
 * from nothing else: never from a casilla number, a position, or a label that
 * reads like a total. The set is total over `InputKind`, so every row has
 * exactly one role and none is guessed.
 *
 * Attributes: INPUT: A figure supplied to the calculation, by the operator or
 * by a resolved binding. COMPUTED: A registry formula derived it from other
 * rows. SUBTOTAL: A settlement-chain figure short of the declaration's result
 * -- the liquidaci�n cell an operator reads on the way to the total. RESULT:
 * The figure the declaration settles. INFORMATIONAL: Declared informational:
 * reported but outside the settlement arithmetic. PROJECTION_ONLY: Declared
 * for projection only, so it reaches the filed artefact without taking part in
 * the calculation.
 */
export type CalculationReportRowRole =
  | "input"
  | "computed"
  | "subtotal"
  | "result"
  | "informational"
  | "projection_only";

