/**
 * One durable unresolved source condition found while calculating a revision.
 *
 * Resolver diagnostics are useful calculate-time operator feedback, but a
 * filing-grade verification runs later against the persisted calculation
 * revision. This narrow envelope carries a source condition that reached no
 * binding, without misrepresenting it as source provenance for a computed
 * output.
 *
 * Every reason below must survive to the persisted revision, because each
 * describes a condition the filing cannot treat as complete.
 * `unrouted_observation` is a row no binding consumes at all.
 * `unrouted_declarable_quantity` is an independent quantity that consumed rows
 * carry and no binding drawing that quantity reaches — the row-keyed screens
 * are silent on it by construction, so a verify or export gate that saw only
 * the row condition would read their silence as confirmation.
 * `iva_selected_scope_evidence_failure` is a ledger IVA row whose selected
 * filing scope cannot be completed from its recorded tax evidence.
 * `iva_compensation_annual_source_evidence_failure` is a required Modelo 390
 * annual partition whose filed Modelo 303 source set is incomplete or stale.
 * `withholding_detail_absent` is an annual withholding summary whose per-
 * perceptor-clave detail store held no observation for the year, so its
 * percepciones count rests on a zero the store cannot support. A contradictory
 * source is refused during calculation before a revision can be persisted.
 *
 * The remaining reasons each mean a filed figure is missing or cannot be
 * trusted. `unresolved_binding` is a box printed on the form whose declared
 * source produced no value, named by `casilla_id`, which must never read as a
 * zero. `unhandled_binding_source` is a declared source with no executable
 * route. `source_domain_not_ready` is a source store that could not be read
 * yet. `invoice_reverse_charge_cuota_not_derivable` is a reverse-charge
 * invoice whose IVA owed could not be derived. These four block filing until a
 * recalculation clears them. `terminal_origin_mismatch` is a value that
 * reached the declaration by an undeclared route; it persists so a reopened
 * declaration still shows it, but withholds nothing, because the route it
 * reports may lack a terminal origin by design. `binding_source` is `None`
 * only where the condition names no binding source kind.
 */
export type CalculationSourceIssue = {
  reason:
    | "unrouted_observation"
    | "unrouted_declarable_quantity"
    | "iva_selected_scope_evidence_failure"
    | "iva_compensation_annual_source_evidence_failure"
    | "withholding_detail_absent"
    | "unresolved_binding"
    | "terminal_origin_mismatch"
    | "unhandled_binding_source"
    | "source_domain_not_ready"
    | "invoice_reverse_charge_cuota_not_derivable";
  binding_source: BindingSourceKind | null;
  message: string;
  resolver_id: string | null;
  source_ref: string | null;
  casilla_id: CasillaId | null;
};

/**
 * A persisted source node's role in one resolver-produced provenance graph.
 */
export type CalculationSourceLineageRole = "primary" | "contributor";

/**
 * One resolver-level source-object trace persisted on a calculation revision.
 *
 * The calculation source mesh (`cadrumo.application.aggregation`) resolves
 * each registry binding source through an enrolled resolver and produces a
 * typed `CalculationSourceProvenance` row per contributing source object. This
 * is the DOMAIN-side, persistence-shaped projection of that provenance: it
 * carries exactly the resolver→source-object→fingerprint trace that lets
 * an audit reader reconstruct which resolver mesh and which upstream source
 * objects produced a revision, and whether those objects have since drifted.
 *
 * It deliberately does NOT carry `legal_refs` / `source_refs` — those are
 * the per-casilla regulatory grounding already carried by `CasillaObservation`
 * on the same revision; duplicating them here would fragment the grounding
 * across two surfaces.
 *
 * `source_casilla_ids` is NOT grounding and the rationale above does not
 * extend to it. It is a subject IDENTITY -- which casilla(s), if any, this
 * source object's resolution feeds -- and nothing else on the revision carries
 * it for the general (non-row-materialized) case; dropping it here was an
 * omission the application-side `CalculationSourceProvenance` did not itself
 * make (it already carries the field). An empty tuple is honest when the
 * originating resolver call site did not associate this row with a casilla —
 * it is not fabricated as a claim of "no subject", only carried as "not linked
 * at resolution time".
 *
 * Attributes: resolver_id: Exact canonical resolver identity that produced
 * this row. resolved_binding_source: Canonical binding source owned by the
 * resolver. contributor_source_kind: Upstream taxonomy token for this source
 * node. contributor_binding_source: Canonical `BindingSourceKind` when
 * `contributor_source_kind` belongs to the binding taxonomy; `None` for an
 * external or non-binding contributor. lineage_role: Whether this row is the
 * resolver-owned primary or supporting contributor. source_ref: Stable
 * reference to the contributing source object (e.g.
 * `collectible_invoice:{invoice_id}`). fingerprint: Data-dependent digest of
 * the contributing source object when the resolver produced one; `None` when
 * the resolver emits a reference without a content digest. source_casilla_ids:
 * Casilla identities this source object's resolution feeds, when the
 * originating resolver associated one; empty when it did not. Carried straight
 * from `source_casilla_ids`. dependency_treatment: The registry's declared
 * dependency treatment for this carry, empty when the revision declares none.
 * Unlike `legal_refs` / `source_refs` this carries no grounding duplicated
 * elsewhere on the revision — it is the sole persisted trace of whether a
 * carry is a `factual_evidence` fact to reconcile against or a
 * `direct_annual_settlement` figure that settles the return, and an audit
 * reader has no other way to recover that distinction after the fact. Carried
 * here rather than gated here: the value is NOT withheld on the basis of its
 * treatment. source_filing_year: The filing year of the source this node rests
 * on, when the resolver recorded one: the source modelo's year for a relation
 * carry, and the accrual year for a Modelo 193 disclosure phase row, which
 * tells a pending row from a settled prior-accrual one. `None` means the year
 * is unknown, including on every revision persisted before the field existed;
 * it never means "the current year". It joins the revision identity only when
 * present, so those revisions keep their content-addressed ids.
 */
export type CalculationSourceRef = {
  resolver_id: string;
  resolved_binding_source: BindingSourceKind;
  contributor_source_kind: string;
  contributor_binding_source: BindingSourceKind | null;
  lineage_role: CalculationSourceLineageRole;
  source_ref: string;
  parent_source_ref: string | null;
  fingerprint: string | null;
  source_casilla_ids: CasillaId[];
  dependency_treatment: string;
  source_filing_year: number | null;
};

