/**
 * Wire mirror of ModeloEditDetailRowAddressV1 carrying the key's components.
 *
 * The domain address holds a `natural_key`: the row's own identity fields
 * joined with `|`. That joined string is a bounded free-form string, which is
 * the same shape a passphrase has, so the credential-free journal check
 * refuses it on the `key` token in its name and no schema predicate could tell
 * the two apart.
 *
 * Nothing is exempted to get around that. The joined string is a derived
 * convenience rather than information: every component is one of the row's own
 * declared identity fields, already carried in the clear by the row mirrors in
 * this module and already admitted by the same check. So the components cross
 * instead, and `to_address` derives the key exactly as the domain type expects
 * it.
 *
 * Carrying the components is also strictly less ambiguous than carrying the
 * join, because a component that itself contains the separator is
 * indistinguishable from a boundary once joined.
 */
export type ModeloEditApplyDetailRowAddressV1 = {
  kind?: "detail_row";
  detail_row_kind: DetailRowKindToken;
  identity_components: string[];
};

