/**
 * Wire mirror of ModeloEditSubmissionV1 carrying a payload-safe baseline.
 *
 * Scalar, binding and row intents are mirrored only for their `value` field:
 * `ModeloScalar` (`Decimal | int | str | bool | date | None`) fails the
 * operations payload-graph gate's validation/serialization schema-identity
 * check, because `Decimal` validates from a number or a string but always
 * serializes to a string. Every other field of these three families -
 * addresses, intent kinds, `move_to_index` - is already payload-safe and
 * carried through unchanged. This is a total translation: every field of every
 * mirrored intent converts, nothing is dropped.
 *
 * `detail_row_intents` is carried, one wire type per per-modelo row kind. Each
 * mirrors its row's `Decimal` fields as the exact characters submitted, and
 * the two kinds that hydrate registry codes carry them raw so the real row
 * type runs its own hydration during translation - one hydration shared with
 * the CLI `--row key=value` path rather than a second copy free to drift.
 *
 * The address is mirrored too, and deliberately not by mirroring its
 * `natural_key`: see `ModeloEditApplyDetailRowAddressV1` for why the
 * components cross instead of the string derived from them.
 *
 * The mirrored payload is INPUT, not authority: `apply_modelo_edit` re-
 * resolves and independently re-validates every coordinate at the guarded
 * commit point regardless of what this wire type carried, so a stale or forged
 * mirror cannot be believed - a mismatch surfaces as the typed no-effect
 * result, never a bad write.
 */
export type ModeloEditApplySubmissionV1 = {
  edit_contract_version?: 1;
  baseline: ModeloEditApplyBaselineV1;
  mutation_family: ModeloEditMutationFamily;
  scalar_intents?: ModeloEditApplyScalarIntentV1[];
  binding_intents?: ModeloEditApplyBindingIntentV1[];
  row_intents?: ModeloEditApplyRowIntentV1[];
  detail_row_intents?: ModeloEditApplyDetailRowIntentV1[];
  lexemes?: ModeloEditParseRequestV1[];
  held?: ModeloEditHeldChangeV1[];
};

