export type QuickfileStageMessage =
  | ""
  | "resumed"
  | "created"
  | "verification did not grant verificado-completo"
  | "readiness could not be resolved; proceeding to calculate"
  | "profile is not yet source-ready; caller-supplied inputs may still satisfy calculate";

/**
 * An ordered canonical status, fixed message, closed facts and recovery
 * verdict.
 */
export type QuickfileStageSnapshot = {
  stage: QuickfileStage;
  status: QuickfileStageStatus;
  message: QuickfileStageMessage;
  facts: QuickfileStageFacts;
  error: QuickfileStageError | null;
  precondition_verdict: PreconditionVerdictSnapshot | null;
};

/**
 * Outcome status for one quickfile stage.
 *
 * `OK` � the stage completed and the chain may proceed. `WARNING` � the stage
 * completed but surfaced a non-blocking advisory (e.g. readiness reported the
 * profile is not yet source-ready, which a caller-supplied `--binding` may
 * still satisfy). `REFUSED` � the stage refused and the chain halted here.
 * `SKIPPED` � a downstream stage that never ran because an earlier stage
 * refused.
 */
export type QuickfileStageStatus = "ok" | "warning" | "refused" | "skipped";

export type QuickfileText = string;

